import { Node } from './node';
import { NodeMapping } from './node-mapping';

export const Video = {
    NodeMapping,
    Node
};

import { Node as TiptapNode } from '@tiptap/core';
import { ReactNodeViewRenderer } from '@tiptap/react';

import { NodeView } from './node-view';

export const Node = TiptapNode.create({
    name: 'video',
    group: 'block',
    atom: true,
    addAttributes() {
        return {
            src: {
                default: null,
                parseHTML: element => {
                    const value = element.getAttribute('data-src');

                    return value || null;
                },
                renderHTML: ({ src }) => {
                    if (!src) {
                        return {};
                    }

                    return { 'data-src': src };
                }
            },
            autoplay: {
                default: false,
                parseHTML: element => {
                    const value = element.getAttribute('data-autoplay');

                    return value === 'true';
                },
                renderHTML: ({ autoplay }) => {
                    return { 'data-autoplay': autoplay };
                }
            },
            controls: {
                default: true,
                parseHTML: element => {
                    const value = element.getAttribute('data-controls');

                    return value === 'true';
                },
                renderHTML: ({ controls }) => {
                    return { 'data-controls': controls };
                }
            },
            loop: {
                default: false,
                parseHTML: element => {
                    const value = element.getAttribute('data-loop');

                    return value === 'true';
                },
                renderHTML: ({ loop }) => {
                    return { 'data-loop': loop };
                }
            },
            muted: {
                default: false,
                parseHTML: element => {
                    const value = element.getAttribute('data-muted');

                    return value === 'true';
                },
                renderHTML: ({ muted }) => {
                    return { 'data-muted': muted };
                }
            },
            preload: {
                default: 'metadata',
                parseHTML: element => {
                    return element.getAttribute('data-preload') || 'metadata';
                },
                renderHTML: ({ preload }) => {
                    return { 'data-preload': preload };
                }
            },
            playsinline: {
                default: false,
                parseHTML: element => {
                    const value = element.getAttribute('data-playsinline');

                    return value === 'true';
                },
                renderHTML: ({ playsinline }) => {
                    return { 'data-playsinline': playsinline };
                }
            },
            crossOrigin: {
                default: null,
                parseHTML: element => element.getAttribute('data-crossorigin'),
                renderHTML: ({ crossOrigin }) => {
                    if (!crossOrigin) {
                        return {};
                    }

                    return { 'data-crossorigin': crossOrigin };
                }
            },
            poster: {
                default: null,
                parseHTML: element => element.getAttribute('data-poster'),
                renderHTML: ({ poster }) => {
                    if (!poster) {
                        return {};
                    }

                    return { 'data-poster': poster };
                }
            }
        };
    },
    renderHTML({ HTMLAttributes }) {
        const attrs = {
            'data-slot': 'video',
            ...HTMLAttributes
        };

        const div = document.createElement('div');
        Object.entries(attrs).forEach(([key, value]) => {
            if (value !== null && value !== undefined) {
                div.setAttribute(key, value);
            }
        });

        return div;
    },
    addNodeView: () => ReactNodeViewRenderer(NodeView)
});

import { type ReactNodeViewProps } from '@tiptap/react';
import { NodeViewWrapper } from '@tiptap/react';

import { NodeMapping } from './node-mapping';

export const NodeView = ({ node }: ReactNodeViewProps) => {
    const value = node!.attrs as {
        src: string | null;
        autoplay: boolean;
        controls: boolean;
        loop: boolean;
        muted: boolean;
        preload: 'metadata' | 'none' | 'auto';
        playsinline: boolean;
        crossOrigin: 'anonymous' | 'use-credentials' | null;
        poster: string | null;
    };

    return (
        <NodeViewWrapper
            // data-slot="video"
            data-src={value.src}
            data-autoplay={value.autoplay}
            data-controls={value.controls}
            data-loop={value.loop}
            data-muted={value.muted}
            data-preload={value.preload}
            data-playsinline={value.playsinline}
            data-crossorigin={value.crossOrigin}
            data-poster={value.poster}
        >
            <div className="p-px">
                <NodeMapping
                    src={value.src || undefined}
                    autoPlay={value.autoplay}
                    controls={value.controls}
                    loop={value.loop}
                    muted={value.muted}
                    preload={value.preload}
                    playsInline={value.playsinline}
                    crossOrigin={value.crossOrigin}
                    poster={value.poster || undefined}
                />
            </div>
        </NodeViewWrapper>
    );
};

import { NodeViewWrapper } from '@tiptap/react';
import { type MediaHTMLAttributes } from 'react';

export const NodeMapping = ({
    src,
    autoPlay,
    controls,
    loop,
    muted,
    preload,
    playsInline,
    crossOrigin,
    poster
}: {
    src?: string;
    autoPlay?: boolean;
    controls?: boolean;
    loop?: boolean;
    muted?: boolean;
    preload?: 'metadata' | 'none' | 'auto';
    playsInline?: boolean;
    crossOrigin?: 'anonymous' | 'use-credentials' | null;
    poster?: string;
}) => {
    //

    return (
        <NodeViewWrapper data-slot="video">
            <div className="relative isolate w-full overflow-hidden bg-black">
                <video
                    className="aspect-video w-full"
                    src={src}
                    autoPlay={autoPlay}
                    controls={controls}
                    loop={loop}
                    muted={muted}
                    preload={preload}
                    playsInline={playsInline}
                    crossOrigin={
                        crossOrigin as MediaHTMLAttributes<'video'>['crossOrigin']
                    }
                    poster={poster}
                />
            </div>
        </NodeViewWrapper>
    );
};
